from pysat.solvers import Glucose3
from itertools import combinations

n = 27
fixed = {9:23, 12:13, 18:1, 21:21, 26:14}

# Variable for position (row, col): row*n + col + 1
def var(r, c):
    return r * n + c + 1

cnf = []

# One queen per row
for r in range(n):
    row_vars = [var(r, c) for c in range(n)]
    cnf.append(row_vars)  # at least one
    for pair in combinations(row_vars, 2):
        cnf.append([-x for x in pair])  # at most one

# One queen per column
for c in range(n):
    col_vars = [var(r, c) for r in range(n)]
    for pair in combinations(col_vars, 2):
        cnf.append([-x for x in pair])

# Diagonals: main diagonals (r - c = constant)
for d in range(-n+1, n):
    diag_vars = [var(r, c) for r in range(n) for c in range(n) if r - c == d]
    if len(diag_vars) > 1:
        for pair in combinations(diag_vars, 2):
            cnf.append([-x for x in pair])

# Anti-diagonals (r + c = constant)
for s in range(2*n - 1):
    antidiag_vars = [var(r, c) for r in range(n) for c in range(n) if r + c == s]
    if len(antidiag_vars) > 1:
        for pair in combinations(antidiag_vars, 2):
            cnf.append([-x for x in pair])

# Fixed positions
for r, c in fixed.items():
    v = var(r, c)
    cnf.append([v])  # must be true

# Now solve
solver = Glucose3()
solver.append_formula(cnf)
status = solver.solve()
print("Satisfiable:", status)
if status:
    model = solver.get_model()
    solution = [-1] * n
    for r in range(n):
        for c in range(n):
            if var(r, c) in model:  # positive means true
                solution[r] = c
                break
    print(solution)
else:
    print("UNSATISFIABLE")
